Not sure about that one but what about this fix ? @Seluj78

```
 // event.ts

 export class Subscription {
   private readonly shellSnapshots = new Map<string, string>()
   private readonly toolStarts = new Set<string>()
+  private readonly pendingPermissions = new Map<string, string>()  // toolCallID → requestID
   private readonly permission: ACPPermission.Handler
   private started = false

   async handle(event: Event) {
     switch (event.type) {
       case "permission.asked":
+        if (event.properties.tool?.callID)
+          this.pendingPermissions.set(event.properties.tool.callID, event.properties.id)
         this.permission.handle(event)
         return
+      case "permission.replied":
+        for (const [callID, reqID] of this.pendingPermissions)
+          if (reqID === event.properties.requestID) { this.pendingPermissions.delete(callID); break }
+        return
       case "message.part.updated":
         return this.handlePartUpdated(event)

   private async runningTool(sessionId, part, cwd) {
+    if (this.pendingPermissions.has(part.callID)) return  // keep "pending" until permission resolved
     const output = part.tool === "bash" ? shellOutputSnapshot(part.state) : undefined
```
